//#region collectors/element-timing-collector.ts
/**
* Generates a simple CSS selector for an element
*/
function getSimpleSelector(element) {
	if (!element) return "unknown";
	if (element.id) return `#${element.id}`;
	const timing = element.getAttribute("elementtiming");
	if (timing) return `[elementtiming="${timing}"]`;
	const classes = element.className ? `.${element.className.split(/\s+/).filter((c) => c).slice(0, 2).join(".")}` : "";
	return `${element.tagName.toLowerCase()}${classes}`;
}
/**
* Collects Element Timing metrics for elements with the `elementtiming` attribute.
*
* This collector is useful for:
* - Measuring when hero images or key content render
* - Tracking Largest Contentful Paint candidates
* - Debugging slow-rendering components
*/
var ElementTimingCollector = class {
	#observer = null;
	#supported = false;
	#elements = [];
	#largestRenderTime = 0;
	/** Entries with renderTime/loadTime before this threshold are ignored (stale from before reset). */
	#epochMs = 0;
	constructor() {
		this.#supported = this.#checkSupport();
	}
	#checkSupport() {
		try {
			return typeof PerformanceObserver !== "undefined" && PerformanceObserver.supportedEntryTypes.includes("element");
		} catch {
			return false;
		}
	}
	start() {
		if (!this.#supported) return;
		this.#epochMs = performance.now();
		try {
			this.#observer = new PerformanceObserver((list) => {
				for (const entry of list.getEntries()) this.#processEntry(entry);
			});
			this.#observer.observe({
				type: "element",
				buffered: true
			});
		} catch {
			this.#supported = false;
		}
	}
	#processEntry(entry) {
		const renderTime = entry.renderTime || entry.loadTime || 0;
		if (renderTime < this.#epochMs) return;
		const record = {
			identifier: entry.identifier || "unnamed",
			renderTime,
			loadTime: entry.loadTime || 0,
			selector: getSimpleSelector(entry.element),
			tagName: entry.element?.tagName.toLowerCase() ?? "unknown"
		};
		if (entry.naturalWidth) {
			record.naturalWidth = entry.naturalWidth;
			record.naturalHeight = entry.naturalHeight;
		}
		if (entry.url) record.url = entry.url;
		this.#elements.push(record);
		if (renderTime > this.#largestRenderTime) this.#largestRenderTime = renderTime;
	}
	stop() {
		this.#observer?.disconnect();
		this.#observer = null;
	}
	reset() {
		this.#elements = [];
		this.#largestRenderTime = 0;
		this.#epochMs = performance.now();
	}
	getMetrics() {
		return {
			elementTimingSupported: this.#supported,
			elements: this.#elements,
			largestRenderTime: this.#largestRenderTime,
			elementCount: this.#elements.length
		};
	}
};

//#endregion
//#region collectors/forced-reflow-collector.ts
/**
* Detects forced synchronous layout (reflows).
*
* Instruments layout-triggering property getters AND layout-affecting
* CSS property setters to detect when layout properties are read
* immediately after style writes (synchronously, within the same task).
*/
var ForcedReflowCollector = class ForcedReflowCollector {
	#forcedReflowCount = 0;
	#layoutDirty = false;
	#dirtyTimeout = null;
	static #registry = null;
	/** Layout-triggering property getters on HTMLElement */
	static #REFLOW_PROPS = [
		"offsetTop",
		"offsetLeft",
		"offsetWidth",
		"offsetHeight",
		"scrollTop",
		"scrollLeft",
		"scrollWidth",
		"scrollHeight",
		"clientTop",
		"clientLeft",
		"clientWidth",
		"clientHeight"
	];
	/** CSS properties whose writes invalidate layout (trigger reflow when subsequently read) */
	static #LAYOUT_STYLE_PROPS = [
		"width",
		"height",
		"minWidth",
		"minHeight",
		"maxWidth",
		"maxHeight",
		"padding",
		"paddingTop",
		"paddingRight",
		"paddingBottom",
		"paddingLeft",
		"margin",
		"marginTop",
		"marginRight",
		"marginBottom",
		"marginLeft",
		"borderWidth",
		"borderTopWidth",
		"borderRightWidth",
		"borderBottomWidth",
		"borderLeftWidth",
		"display",
		"position",
		"top",
		"left",
		"right",
		"bottom",
		"fontSize",
		"lineHeight",
		"boxSizing",
		"overflow"
	];
	markLayoutDirty() {
		this.#layoutDirty = true;
		if (this.#dirtyTimeout) clearTimeout(this.#dirtyTimeout);
		this.#dirtyTimeout = setTimeout(() => {
			this.#layoutDirty = false;
		}, 0);
	}
	start() {
		if (!ForcedReflowCollector.#registry) ForcedReflowCollector.#registry = {
			initialized: false,
			originalGetters: /* @__PURE__ */ new Map(),
			originalStyleSetters: /* @__PURE__ */ new Map(),
			originalSetProperty: null,
			activeCollectors: /* @__PURE__ */ new Set(),
			currentCollector: null
		};
		const registry = ForcedReflowCollector.#registry;
		registry.activeCollectors.add(this);
		registry.currentCollector = this;
		if (!registry.initialized) {
			registry.initialized = true;
			for (const prop of ForcedReflowCollector.#REFLOW_PROPS) {
				const descriptor = Object.getOwnPropertyDescriptor(HTMLElement.prototype, prop);
				if (descriptor?.get) {
					registry.originalGetters.set(prop, descriptor);
					Object.defineProperty(HTMLElement.prototype, prop, {
						get() {
							const collector = ForcedReflowCollector.#registry?.currentCollector;
							if (collector && collector.#layoutDirty) {
								collector.#forcedReflowCount++;
								collector.#layoutDirty = false;
							}
							return descriptor.get?.call(this);
						},
						configurable: true
					});
				}
			}
			for (const prop of ForcedReflowCollector.#LAYOUT_STYLE_PROPS) {
				const descriptor = Object.getOwnPropertyDescriptor(CSSStyleDeclaration.prototype, prop);
				if (descriptor?.set) {
					registry.originalStyleSetters.set(prop, descriptor);
					const origSet = descriptor.set;
					Object.defineProperty(CSSStyleDeclaration.prototype, prop, {
						...descriptor,
						set(value) {
							ForcedReflowCollector.#registry?.currentCollector?.markLayoutDirty();
							origSet.call(this, value);
						}
					});
				}
			}
			const origSetProperty = CSSStyleDeclaration.prototype.setProperty;
			registry.originalSetProperty = origSetProperty;
			CSSStyleDeclaration.prototype.setProperty = function(property, value, priority) {
				ForcedReflowCollector.#registry?.currentCollector?.markLayoutDirty();
				origSetProperty.call(this, property, value, priority ?? "");
			};
		}
	}
	stop() {
		if (this.#dirtyTimeout) {
			clearTimeout(this.#dirtyTimeout);
			this.#dirtyTimeout = null;
		}
		const registry = ForcedReflowCollector.#registry;
		if (!registry) return;
		registry.activeCollectors.delete(this);
		if (registry.currentCollector === this) registry.currentCollector = null;
		if (registry.activeCollectors.size === 0 && registry.initialized) {
			for (const [prop, descriptor] of registry.originalGetters) Object.defineProperty(HTMLElement.prototype, prop, descriptor);
			registry.originalGetters.clear();
			for (const [prop, descriptor] of registry.originalStyleSetters) Object.defineProperty(CSSStyleDeclaration.prototype, prop, descriptor);
			registry.originalStyleSetters.clear();
			if (registry.originalSetProperty) {
				CSSStyleDeclaration.prototype.setProperty = registry.originalSetProperty;
				registry.originalSetProperty = null;
			}
			registry.initialized = false;
		}
	}
	reset() {
		this.#forcedReflowCount = 0;
		this.#layoutDirty = false;
	}
	getMetrics() {
		return { forcedReflowCount: this.#forcedReflowCount };
	}
};

