//#region collectors/layout-shift-collector.ts
/** Maximum gap between shifts in a session (1 second) */
const SESSION_GAP_MS = 1e3;
/** Maximum duration of a session window (5 seconds) */
const SESSION_MAX_DURATION_MS = 5e3;
/**
* Collects Cumulative Layout Shift (CLS) metrics using session windowing.
*
* Per the Core Web Vitals spec, CLS uses session windows:
* - A session is a group of layout shifts with <1s gaps
* - A session cannot exceed 5s total duration
* - CLS is the maximum session window value
*
* @see https://web.dev/articles/evolving-cls
*/
var LayoutShiftCollector = class {
	/** Maximum session window value (the actual CLS score) */
	#maxSessionScore = 0;
	/** Current session's cumulative score */
	#currentSessionScore = 0;
	/** First entry's startTime in current session */
	#sessionFirstEntryTime = null;
	/** Last entry's startTime in current session */
	#sessionLastEntryTime = null;
	/** Total count of layout shift events */
	#layoutShiftCount = 0;
	/** Number of completed sessions */
	#sessionCount = 0;
	#observer = null;
	start() {
		try {
			this.#observer = new PerformanceObserver((list) => {
				for (const entry of list.getEntries()) this.#processEntry(entry);
			});
			this.#observer.observe({
				type: "layout-shift",
				buffered: true
			});
		} catch {}
	}
	#processEntry(entry) {
		if (entry.hadRecentInput) return;
		this.#layoutShiftCount++;
		if (this.#sessionFirstEntryTime === null || this.#sessionLastEntryTime === null || entry.startTime - this.#sessionLastEntryTime >= SESSION_GAP_MS || entry.startTime - this.#sessionFirstEntryTime >= SESSION_MAX_DURATION_MS) {
			if (this.#currentSessionScore > 0) {
				this.#sessionCount++;
				if (this.#currentSessionScore > this.#maxSessionScore) this.#maxSessionScore = this.#currentSessionScore;
			}
			this.#currentSessionScore = entry.value;
			this.#sessionFirstEntryTime = entry.startTime;
		} else this.#currentSessionScore += entry.value;
		this.#sessionLastEntryTime = entry.startTime;
		if (this.#currentSessionScore > this.#maxSessionScore) this.#maxSessionScore = this.#currentSessionScore;
	}
	stop() {
		this.#observer?.disconnect();
		this.#observer = null;
	}
	reset() {
		this.#maxSessionScore = 0;
		this.#currentSessionScore = 0;
		this.#sessionFirstEntryTime = null;
		this.#sessionLastEntryTime = null;
		this.#layoutShiftCount = 0;
		this.#sessionCount = 0;
	}
	getMetrics() {
		return {
			layoutShiftScore: Math.round(this.#maxSessionScore * 1e4) / 1e4,
			layoutShiftCount: this.#layoutShiftCount,
			currentSessionScore: Math.round(this.#currentSessionScore * 1e4) / 1e4,
			sessionCount: this.#sessionCount
		};
	}
};

//#endregion
//#region collectors/long-animation-frame-collector.ts
/** Rolling window size for LoAF duration history */
const LOAF_HISTORY_WINDOW = 50;
/**
* Collects Long Animation Frame metrics using PerformanceObserver.
*
* The Long Animation Frames API provides detailed attribution for what
* caused frames to exceed 50ms, including:
* - Total frame duration and blocking duration
* - Render and style/layout timing
* - Script attribution (which scripts contributed)
*
* This is more detailed than Long Tasks API and specifically targets
* animation/rendering performance.
*
* @see https://web.dev/articles/long-animation-frames
*/
var LongAnimationFrameCollector = class {
	#loafSupported = false;
	#loafCount = 0;
	#totalBlockingDuration = 0;
	#longestLoafDuration = 0;
	#longestLoafBlockingDuration = 0;
	#loafDurations = [];
	#loafsWithScripts = 0;
	#lastLoaf = null;
	#worstLoaf = null;
	#observer = null;
	constructor() {
		this.#loafSupported = this.#checkSupport();
	}
	#checkSupport() {
		try {
			return PerformanceObserver.supportedEntryTypes.includes("long-animation-frame");
		} catch {
			return false;
		}
	}
	start() {
		if (!this.#loafSupported) return;
		try {
			this.#observer = new PerformanceObserver((list) => {
				for (const entry of list.getEntries()) this.#processEntry(entry);
			});
			this.#observer.observe({
				type: "long-animation-frame",
				buffered: true
			});
		} catch {
			this.#loafSupported = false;
		}
	}
	#processEntry(entry) {
		this.#loafCount++;
		this.#totalBlockingDuration += entry.blockingDuration;
		addToWindow(this.#loafDurations, entry.duration, LOAF_HISTORY_WINDOW);
		const scripts = entry.scripts ?? [];
		if (scripts.length > 0) this.#loafsWithScripts++;
		let topScript = null;
		if (scripts.length > 0) {
			const top = [...scripts].sort((a, b) => b.duration - a.duration)[0];
			if (top) topScript = {
				sourceURL: top.sourceURL || "unknown",
				sourceFunctionName: top.sourceFunctionName || "anonymous",
				sourceCharPosition: top.sourceCharPosition,
				invokerType: top.invokerType,
				invoker: top.invoker || "unknown",
				executionStart: top.executionStart,
				duration: top.duration
			};
		}
		const frameDetails = {
			duration: entry.duration,
			blockingDuration: entry.blockingDuration,
			renderStart: entry.renderStart,
			styleAndLayoutStart: entry.styleAndLayoutStart,
			scriptCount: scripts.length,
			topScript
		};
		this.#lastLoaf = frameDetails;
		if (entry.duration > this.#longestLoafDuration) {
			this.#longestLoafDuration = entry.duration;
			this.#longestLoafBlockingDuration = entry.blockingDuration;
			this.#worstLoaf = frameDetails;
		}
	}
	stop() {
		this.#observer?.disconnect();
		this.#observer = null;
	}
	reset() {
		this.#loafCount = 0;
		this.#totalBlockingDuration = 0;
		this.#longestLoafDuration = 0;
		this.#longestLoafBlockingDuration = 0;
		this.#loafDurations = [];
		this.#loafsWithScripts = 0;
		this.#lastLoaf = null;
		this.#worstLoaf = null;
	}
	getMetrics() {
		return {
			loafSupported: this.#loafSupported,
			loafCount: this.#loafCount,
			totalLoafBlockingDuration: Math.round(this.#totalBlockingDuration),
			longestLoafDuration: Math.round(this.#longestLoafDuration),
			longestLoafBlockingDuration: Math.round(this.#longestLoafBlockingDuration),
			avgLoafDuration: Math.round(computeAverage(this.#loafDurations)),
			p95LoafDuration: Math.round(computeP95(this.#loafDurations)),
			loafsWithScripts: this.#loafsWithScripts,
			lastLoaf: this.#lastLoaf,
			worstLoaf: this.#worstLoaf
		};
	}
};

//#endregion
//#region collectors/main-thread-collector.ts
/**
* Collects main thread health metrics using PerformanceObserver.
*
* Tracks:
* - Long task count (>50ms)
* - Longest task duration
* - Total Blocking Time (TBT)
*/
var MainThreadCollector = class {
	#longTasks = 0;
	#longestTask = 0;
	#totalBlockingTime = 0;
	#observer = null;
	start() {
		try {
			this.#observer = new PerformanceObserver((list) => {
				for (const entry of list.getEntries()) {
					this.#longTasks++;
					if (entry.duration > this.#longestTask) this.#longestTask = entry.duration;
					this.#totalBlockingTime += Math.max(0, entry.duration - 50);
				}
			});
			this.#observer.observe({ type: "longtask" });
		} catch {}
	}
	stop() {
		this.#observer?.disconnect();
		this.#observer = null;
	}
	reset() {
		this.#longTasks = 0;
		this.#longestTask = 0;
		this.#totalBlockingTime = 0;
	}
	getMetrics() {
		return {
			longTasks: this.#longTasks,
			longestTask: this.#longestTask,
			totalBlockingTime: this.#totalBlockingTime
		};
	}
};

//#endregion
//#region collectors/memory-collector.ts
/**
* @fileoverview Memory usage metrics collector
* @module collectors/MemoryCollector
*/
/**
* Collects memory usage metrics (Chrome only).
*
* Tracks:
* - Current heap usage
* - Baseline and peak
* - Memory history for sparklines
* - GC pressure (allocation rate)
*/
var MemoryCollector = class {
	#baselineMemoryMB = null;
	#peakMemoryMB = null;
	#lastMemoryMB = null;
	#memoryHistory = [];
	#gcPressure = 0;
	#lastGcCheckTime = 0;
	#lastGcMemory = null;
	start() {
		const memory = getMemoryMB();
		this.#baselineMemoryMB = memory;
		this.#peakMemoryMB = memory;
		this.#lastMemoryMB = memory;
		this.#lastGcCheckTime = performance.now();
		this.#lastGcMemory = memory;
	}
	stop() {}
	reset() {
		const memory = getMemoryMB();
		this.#baselineMemoryMB = memory;
		this.#peakMemoryMB = memory;
		this.#lastMemoryMB = memory;
		this.#memoryHistory = [];
		this.#gcPressure = 0;
		this.#lastGcCheckTime = performance.now();
		this.#lastGcMemory = memory;
	}
	/** Call periodically to update memory metrics */
	update() {
		const memory = getMemoryMB();
		if (memory === null) return;
		this.#lastMemoryMB = memory;
		if (this.#baselineMemoryMB === null) this.#baselineMemoryMB = memory;
		if (this.#peakMemoryMB === null || memory > this.#peakMemoryMB) this.#peakMemoryMB = memory;
		addToWindow(this.#memoryHistory, memory, SPARKLINE_HISTORY_SIZE);
		this.#updateGcPressure(memory);
	}
	getMetrics() {
		return {
			baselineMemoryMB: this.#baselineMemoryMB,
			peakMemoryMB: this.#peakMemoryMB,
			lastMemoryMB: this.#lastMemoryMB,
			memoryHistory: this.#memoryHistory,
			gcPressure: this.#gcPressure
		};
	}
	#updateGcPressure(currentMemory) {
		const now = performance.now();
		if (this.#lastGcMemory !== null) {
			const timeDelta = (now - this.#lastGcCheckTime) / 1e3;
			if (timeDelta > 0) {
				const memoryDelta = currentMemory - this.#lastGcMemory;
				if (memoryDelta > 0) this.#gcPressure = memoryDelta / timeDelta;
				else this.#gcPressure *= .9;
			}
		}
		this.#lastGcCheckTime = now;
		this.#lastGcMemory = currentMemory;
	}
};

