//#region collectors/paint-collector.ts
/**
* Schedule work during browser idle periods.
* Falls back to setTimeout for environments without requestIdleCallback (e.g. Safari).
*/
function scheduleIdle(callback, options) {
	if (typeof requestIdleCallback === "function") return requestIdleCallback(callback, options);
	return setTimeout(callback, 0);
}
function cancelIdle(id) {
	if (typeof cancelIdleCallback === "function") cancelIdleCallback(id);
	else clearTimeout(id);
}
/**
* Collects paint and resource timing metrics.
*
* Compositor layer tracking uses a MutationObserver to incrementally detect
* style/class/childList changes and defers getComputedStyle checks to idle
* periods via requestIdleCallback, avoiding the observer effect of inflating
* frame timing and main thread metrics.
*/
var PaintCollector = class {
	#paintCount = 0;
	#scriptEvalTime = 0;
	#compositorLayers = null;
	/** Elements currently known to have compositor-layer-promoting properties */
	#layerElements = /* @__PURE__ */ new Set();
	/** Elements whose layer status needs rechecking (attribute changed) */
	#pendingChecks = /* @__PURE__ */ new Set();
	/** Subtree roots that were added and need scanning */
	#pendingSubtrees = [];
	/** Whether removed nodes need cleanup from #layerElements */
	#hasRemovals = false;
	/** Pending idle callback ID */
	#idleCallbackId = null;
	#paintObserver = null;
	#resourceObserver = null;
	#layerObserver = null;
	start() {
		try {
			this.#paintObserver = new PerformanceObserver((list) => {
				this.#paintCount += list.getEntries().length;
			});
			this.#paintObserver.observe({
				type: "paint",
				buffered: true
			});
		} catch {}
		try {
			this.#resourceObserver = new PerformanceObserver((list) => {
				for (const entry of list.getEntries()) if (entry.entryType === "resource") {
					const resourceEntry = entry;
					if (resourceEntry.initiatorType === "script") {
						const scriptTime = resourceEntry.responseEnd - resourceEntry.fetchStart;
						if (scriptTime > 0) this.#scriptEvalTime += scriptTime;
					}
				}
			});
			this.#resourceObserver.observe({
				type: "resource",
				buffered: true
			});
		} catch {}
		this.#startLayerTracking();
	}
	stop() {
		this.#paintObserver?.disconnect();
		this.#resourceObserver?.disconnect();
		this.#paintObserver = null;
		this.#resourceObserver = null;
		this.#stopLayerTracking();
	}
	reset() {
		this.#paintCount = 0;
		this.#scriptEvalTime = 0;
		this.#compositorLayers = null;
		this.#layerElements.clear();
		this.#pendingChecks.clear();
		this.#pendingSubtrees = [];
		this.#hasRemovals = false;
		this.#cancelPendingScan();
		if (this.#layerObserver) this.#scheduleFullScan();
	}
	#startLayerTracking() {
		this.#scheduleFullScan();
		this.#layerObserver = new MutationObserver((mutations) => {
			for (const mutation of mutations) if (mutation.type === "attributes") this.#pendingChecks.add(mutation.target);
			else if (mutation.type === "childList") {
				if (mutation.removedNodes.length > 0) this.#hasRemovals = true;
				for (const node of mutation.addedNodes) if (node instanceof Element) this.#pendingSubtrees.push(node);
			}
			this.#scheduleIncrementalScan();
		});
		this.#layerObserver.observe(document.documentElement, {
			attributes: true,
			attributeFilter: ["style", "class"],
			childList: true,
			subtree: true
		});
	}
	#stopLayerTracking() {
		this.#layerObserver?.disconnect();
		this.#layerObserver = null;
		this.#cancelPendingScan();
		this.#pendingChecks.clear();
		this.#pendingSubtrees = [];
		this.#hasRemovals = false;
	}
	#cancelPendingScan() {
		if (this.#idleCallbackId !== null) {
			cancelIdle(this.#idleCallbackId);
			this.#idleCallbackId = null;
		}
	}
	#scheduleFullScan() {
		this.#cancelPendingScan();
		this.#idleCallbackId = scheduleIdle(() => {
			this.#idleCallbackId = null;
			this.#fullScan();
		}, { timeout: 1e3 });
	}
	#scheduleIncrementalScan() {
		if (this.#idleCallbackId !== null) return;
		this.#idleCallbackId = scheduleIdle(() => {
			this.#idleCallbackId = null;
			this.#processIncrementalChanges();
		});
	}
	#fullScan() {
		this.#layerElements.clear();
		this.#pendingChecks.clear();
		this.#pendingSubtrees = [];
		this.#hasRemovals = false;
		for (const el of document.querySelectorAll("*")) if (this.#hasLayerPromotion(el)) this.#layerElements.add(el);
		this.#compositorLayers = this.#layerElements.size;
	}
	#processIncrementalChanges() {
		if (this.#hasRemovals) {
			for (const el of this.#layerElements) if (!el.isConnected) this.#layerElements.delete(el);
			this.#hasRemovals = false;
		}
		for (const root of this.#pendingSubtrees) {
			if (!root.isConnected) continue;
			if (this.#hasLayerPromotion(root)) this.#layerElements.add(root);
			for (const el of root.querySelectorAll("*")) if (this.#hasLayerPromotion(el)) this.#layerElements.add(el);
		}
		this.#pendingSubtrees = [];
		for (const el of this.#pendingChecks) if (!el.isConnected) this.#layerElements.delete(el);
		else if (this.#hasLayerPromotion(el)) this.#layerElements.add(el);
		else this.#layerElements.delete(el);
		this.#pendingChecks.clear();
		this.#compositorLayers = this.#layerElements.size;
	}
	#hasLayerPromotion(el) {
		const style = getComputedStyle(el);
		if (style.willChange && style.willChange !== "auto") return true;
		if (style.perspective && style.perspective !== "none") return true;
		const transform = style.transform;
		if (transform && transform !== "none") {
			if (transform.startsWith("matrix3d") || /translate3d|translateZ|rotate3d|rotateX|rotateY|scale3d|perspective/i.test(transform)) return true;
		}
		return false;
	}
	getMetrics() {
		return {
			paintCount: this.#paintCount,
			scriptEvalTime: this.#scriptEvalTime,
			compositorLayers: this.#compositorLayers
		};
	}
};

