//#region collectors/react-profiler-collector.ts
/**
* Default empty metrics for initialization.
*/
const DEFAULT_REACT_METRICS = {
	reactRenderCount: 0,
	reactMountCount: 0,
	reactMountDuration: 0,
	reactPostMountUpdateCount: 0,
	reactPostMountMaxDuration: 0,
	nestedUpdateCount: 0,
	slowReactUpdates: 0,
	reactUpdateDurations: [],
	totalBaseDuration: 0,
	maxCommitLag: 0,
	commitLagHistory: [],
	memoizationEfficiency: 1,
	totalActualDuration: 0
};
/**
* Creates a fresh ReactMetrics object.
*/
function createEmptyReactMetrics() {
	return {
		...DEFAULT_REACT_METRICS,
		reactUpdateDurations: [],
		commitLagHistory: []
	};
}
/**
* Collects React Profiler metrics with support for multiple profilers.
*
* Tracks per-profiler:
* - Mount count and duration
* - Update count and max duration
* - Nested updates (render cascades)
* - Slow updates (>16ms)
* - P95 calculation data
* - Base duration (theoretical render without memoization)
* - Commit lag (time between render and commit)
*
* Aggregated metrics are computed on-demand from per-profiler data.
*/
var ReactProfilerCollector = class {
	#profilers = /* @__PURE__ */ new Map();
	#onProfilerUpdate;
	start() {}
	stop() {}
	reset() {
		for (const [profilerId, state] of this.#profilers) {
			const profilerMountCount = state.metrics.reactMountCount;
			const profilerMountDuration = state.metrics.reactMountDuration;
			state.metrics = {
				...createEmptyReactMetrics(),
				reactMountCount: profilerMountCount,
				reactMountDuration: profilerMountDuration
			};
			this.#onProfilerUpdate?.(state.storyId, profilerId, state.metrics);
		}
	}
	/**
	* Set callback for profiler updates.
	* Called whenever a profiler's metrics change.
	*/
	setOnProfilerUpdate(callback) {
		this.#onProfilerUpdate = callback;
	}
	/**
	* Clear all profilers. Called on story change.
	*/
	clearProfilers() {
		this.#profilers.clear();
	}
	/**
	* Clear profilers that don't belong to the specified storyId.
	* This allows us to clean up old story data while preserving the current story's mount metrics.
	*/
	clearProfilersExcept(keepStoryId) {
		for (const [id, state] of this.#profilers) if (state.storyId !== keepStoryId) this.#profilers.delete(id);
	}
	/**
	* Get all registered profiler IDs.
	*/
	getProfilerIds() {
		return Array.from(this.#profilers.keys());
	}
	/**
	* Get metrics for a specific profiler.
	*/
	getProfilerMetrics(id) {
		return this.#profilers.get(id)?.metrics;
	}
	/**
	* Report a React render from the Profiler component.
	* Updates per-profiler metrics. Profilers are auto-registered on first report.
	*
	* @param info - Render information from React Profiler callback
	*/
	reportRender = (info) => {
		const commitLag = Math.max(0, info.commitTime - info.startTime - info.actualDuration);
		let state = this.#profilers.get(info.profilerId);
		if (!state) {
			state = {
				metrics: createEmptyReactMetrics(),
				storyId: info.storyId
			};
			this.#profilers.set(info.profilerId, state);
		} else state.storyId = info.storyId;
		this.#updateProfilerMetrics(state, info, commitLag);
		this.#onProfilerUpdate?.(info.storyId, info.profilerId, state.metrics);
	};
	/**
	* Update per-profiler metrics.
	*/
	#updateProfilerMetrics(state, info, commitLag) {
		const { phase, actualDuration, baseDuration } = info;
		const metrics = state.metrics;
		if (phase === "nested-update") metrics.nestedUpdateCount++;
		metrics.reactRenderCount++;
		metrics.totalBaseDuration += baseDuration;
		metrics.totalActualDuration += actualDuration;
		metrics.memoizationEfficiency = metrics.totalBaseDuration > 0 ? metrics.totalActualDuration / metrics.totalBaseDuration : 1;
		if (commitLag > metrics.maxCommitLag) metrics.maxCommitLag = commitLag;
		addToWindow(metrics.commitLagHistory, commitLag, 100);
		if (phase === "mount") {
			metrics.reactMountCount++;
			metrics.reactMountDuration += actualDuration;
		} else {
			metrics.reactPostMountUpdateCount++;
			if (actualDuration > metrics.reactPostMountMaxDuration) metrics.reactPostMountMaxDuration = actualDuration;
			if (actualDuration > 16) metrics.slowReactUpdates++;
			addToWindow(metrics.reactUpdateDurations, actualDuration, 100);
		}
	}
	/**
	* Get aggregated metrics from all profilers.
	* Returns empty metrics if no profilers registered.
	*/
	getMetrics() {
		if (this.#profilers.size === 0) return createEmptyReactMetrics();
		let renderCount = 0;
		let mountCount = 0;
		let mountDuration = 0;
		let updateCount = 0;
		let maxDuration = 0;
		let nestedCount = 0;
		let slowCount = 0;
		let totalBase = 0;
		let totalActual = 0;
		let maxLag = 0;
		const allDurations = [];
		const allLags = [];
		for (const state of this.#profilers.values()) {
			const m = state.metrics;
			renderCount += m.reactRenderCount;
			mountCount += m.reactMountCount;
			mountDuration += m.reactMountDuration;
			updateCount += m.reactPostMountUpdateCount;
			maxDuration = Math.max(maxDuration, m.reactPostMountMaxDuration);
			nestedCount += m.nestedUpdateCount;
			slowCount += m.slowReactUpdates;
			totalBase += m.totalBaseDuration;
			totalActual += m.totalActualDuration;
			maxLag = Math.max(maxLag, m.maxCommitLag);
			allDurations.push(...m.reactUpdateDurations);
			allLags.push(...m.commitLagHistory);
		}
		const memoizationEfficiency = totalBase > 0 ? totalActual / totalBase : 1;
		return {
			reactRenderCount: renderCount,
			reactMountCount: mountCount,
			reactMountDuration: mountDuration,
			reactPostMountUpdateCount: updateCount,
			reactPostMountMaxDuration: maxDuration,
			nestedUpdateCount: nestedCount,
			slowReactUpdates: slowCount,
			reactUpdateDurations: allDurations.slice(-100),
			totalBaseDuration: totalBase,
			maxCommitLag: maxLag,
			commitLagHistory: allLags.slice(-100),
			memoizationEfficiency,
			totalActualDuration: totalActual
		};
	}
};

//#endregion
//#region collectors/style-mutation-collector.ts
/**
* @fileoverview Style mutation and DOM churn metrics collector
* @module collectors/StyleMutationCollector
*/
/**
* Collects style mutation and DOM churn metrics.
*
* Tracks:
* - Style attribute mutations
* - CSS variable changes
* - DOM mutations per frame
* - Layout thrashing score
*/
var StyleMutationCollector = class {
	#styleWrites = 0;
	#cssVarChanges = 0;
	#domMutationFrames = [];
	#thrashingScore = 0;
	#styleWriteCount = 0;
	#lastStyleWriteTime = 0;
	#domMutationCount = 0;
	#observer = null;
	#sampleInterval = null;
	/** Callback when layout becomes dirty (for reflow detection) */
	onLayoutDirty;
	start() {
		this.#observer = new MutationObserver((mutations) => {
			for (const mutation of mutations) if (mutation.type === "attributes" && mutation.attributeName === "style") {
				this.#styleWrites++;
				this.#styleWriteCount++;
				this.#lastStyleWriteTime = performance.now();
				this.onLayoutDirty?.();
				const newValue = mutation.target.getAttribute("style") ?? "";
				const oldValue = mutation.oldValue ?? "";
				const newVars = newValue.match(/--[\w-]+\s*:[^;]*/g);
				const oldVars = oldValue.match(/--[\w-]+\s*:[^;]*/g);
				if (newVars) {
					const oldSet = new Set(oldVars?.map((s) => s.trim()));
					for (const v of newVars) if (!oldSet.has(v.trim())) this.#cssVarChanges++;
				}
			} else if (mutation.type === "childList") this.#domMutationCount += mutation.addedNodes.length + mutation.removedNodes.length;
			else if (mutation.type === "attributes" && mutation.attributeName !== "style") this.#domMutationCount++;
		});
		this.#observer.observe(document.body, {
			childList: true,
			attributes: true,
			attributeOldValue: true,
			subtree: true,
			attributeFilter: [
				"style",
				"class",
				"id",
				"data-state",
				"aria-expanded",
				"aria-hidden",
				"hidden",
				"disabled"
			]
		});
		this.#sampleInterval = setInterval(() => {
			addToWindow(this.#domMutationFrames, this.#domMutationCount, 30);
			this.#domMutationCount = 0;
		}, 200);
	}
	stop() {
		this.#observer?.disconnect();
		if (this.#sampleInterval) clearInterval(this.#sampleInterval);
		this.#observer = null;
		this.#sampleInterval = null;
	}
	reset() {
		this.#styleWrites = 0;
		this.#cssVarChanges = 0;
		this.#domMutationFrames = [];
		this.#thrashingScore = 0;
		this.#styleWriteCount = 0;
		this.#domMutationCount = 0;
	}
	/** Call on each frame to check for thrashing */
	checkThrashing(frameTime) {
		const timeSinceLastWrite = performance.now() - this.#lastStyleWriteTime;
		if (this.#styleWriteCount > 0 && timeSinceLastWrite < THRASHING_STYLE_WRITE_WINDOW && frameTime > THRASHING_FRAME_THRESHOLD) this.#thrashingScore++;
		this.#styleWriteCount = 0;
	}
	getMetrics() {
		return {
			styleWrites: this.#styleWrites,
			cssVarChanges: this.#cssVarChanges,
			domMutationFrames: this.#domMutationFrames,
			thrashingScore: this.#thrashingScore
		};
	}
};

