	frameTime: 0,
	maxFrameTime: 0,
	droppedFrames: 0,
	frameJitter: 0,
	frameStability: 100,
	inputLatency: 0,
	maxInputLatency: 0,
	inputJitter: 0,
	eventTimingSupported: true,
	interactionCount: 0,
	inpMs: 0,
	firstInputDelay: null,
	firstInputType: null,
	lastInteraction: null,
	slowestInteraction: null,
	interactionsByType: {},
	paintTime: 0,
	maxPaintTime: 0,
	paintCount: 0,
	paintJitter: 0,
	memoryUsedMB: null,
	memoryDeltaMB: null,
	peakMemoryMB: null,
	gcPressure: 0,
	fpsHistory: [],
	frameTimeHistory: [],
	memoryHistory: [],
	longTasks: 0,
	longestTask: 0,
	totalBlockingTime: 0,
	loafSupported: true,
	loafCount: 0,
	totalLoafBlockingDuration: 0,
	longestLoafDuration: 0,
	longestLoafBlockingDuration: 0,
	avgLoafDuration: 0,
	p95LoafDuration: 0,
	loafsWithScripts: 0,
	lastLoaf: null,
